INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT142-S1-Q9$batch08$, 142, 1, 9, $batch08$Paradox$batch08$, $batch08$Many calcium supplements contain lead, a potentially dangerous substance even in small amounts. The body can safely store in bones trace amounts of lead from food, but high levels of lead in the blood are a major public health concern, associated with anemia and nerve damage. Despite this, many doctors contend that for some people calcium supplements containing lead are preferable to no calcium supplements at all.$batch08$, $batch08$Which one of the following, if true, would most help to resolve the apparent discrepancy in the information above?$batch08$, $batch08$E$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=142 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q9$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$Some fruits and vegetables contain trace amounts of lead derived from the soil in which they are grown.$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q9$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$It is difficult to ensure that one has completely eliminated trace amounts of lead from one’s diet.$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q9$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$Lead is only one of the common public health concerns that are associated with anemia and nerve damage.$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q9$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$A high-calcium diet decreases the amount of lead that the body is able to tolerate safely.$batch08$, $batch08$Deepens Paradox$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q9$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$When calcium intake is insufficient, the body draws calcium from bones, releasing stored lead into the bloodstream.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q9$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT142-S1-Q9$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Given that$batch08$, $batch08$Many calcium supplements contain lead, which is dangerous even in small amounts, and high blood lead causes anemia and nerve damage.$batch08$), (1, $batch08$How can it be that$batch08$, $batch08$Many doctors say that for some people, supplements containing lead are better than no supplements at all?$batch08$), (2, $batch08$Evaluate$batch08$, $batch08$Notice the detail about bones: the body safely stores trace lead in bones. What if going without calcium shakes that lead loose? Then skipping supplements could put *more* lead in the blood than taking them would.$batch08$), (3, $batch08$Goal$batch08$, $batch08$A way that going without calcium also raises blood lead, and by more.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT142-S1-Q9$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$Lead in food doesn't explain why a leaded supplement would beat no supplement.$batch08$), ($batch08$B$batch08$, $batch08$It's hard to avoid trace lead in food. That still gives no reason to add more through supplements.$batch08$), ($batch08$C$batch08$, $batch08$Other causes of anemia and nerve damage don't make lead any safer.$batch08$), ($batch08$D$batch08$, $batch08$If calcium lowers how much lead the body can handle, calcium supplements with lead look even worse.$batch08$), ($batch08$E$batch08$, $batch08$Without enough calcium, the body pulls it from bone and releases the stored lead into the blood. So no supplement can mean more blood lead than a supplement with a little lead.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT142-S1-Q9$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
